<section class="content-section" id="income"><div class="section-heading"><div><div class="eyebrow">SUBSCRIPTION ANALYSIS</div><h2>Income and renewals</h2><p class="muted">Confirmed subscription value is grouped by currency. Pending requests are not included as income.</p></div></div><form class="results-entry-meta" method="get"><label for="subscription-year">Academic year<input id="subscription-year" type="number" name="year" min="2000" max="2100" value="<?=$analysisYear?>"></label><button class="button" type="submit">Analyze year</button></form>
<div class="section-heading"><div><div class="eyebrow">CONFIRMED PAYMENTS</div><h3>Recorded income · <?=$analysisYear?></h3></div></div><?php if(!$incomeRows):?><p class="muted">No confirmed subscription income for <?=$analysisYear?>.</p><?php else:?><div class="metric-grid"><?php foreach($incomeRows as $income):?><article class="metric-card"><div class="metric-label"><?=e($income['currency'])?> · CONFIRMED INCOME</div><div class="metric-value"><?=e(number_format((float)$income['income'],2))?></div><div class="metric-note"><?=number_format((int)$income['subscription_count'])?> subscriptions · <?=number_format((int)$income['pupils'])?> pupil enrolments</div></article><?php endforeach;?></div><?php endif;?>
<div class="section-heading"><div><div class="eyebrow">RENEWALS</div><h3>Active subscriptions and end dates</h3><p class="muted"><?=$expiredCount?> expired subscription<?=($expiredCount===1?'':'s')?> recorded for <?=$analysisYear?>.</p></div><span class="count-pill"><?=count($activeRows)?> active</span></div><?php if(!$activeRows):?><p class="muted">No active subscriptions for this year.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Plan</th><th>Pupils</th><th>Rate per pupil</th><th>Discount</th><th>Income</th><th>Duration</th><th>Subscription dates</th><th>Days left</th></tr></thead><tbody><?php foreach($activeRows as $s):?><tr><td><?=e($s['school_name'])?></td><td><?=e($s['plan_name'])?></td><td><?=number_format((int)$s['pupil_count'])?></td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['unit_price'],2))?></td><td><?=e(number_format((float)$s['discount_percent'],2))?>%</td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['total_amount'],2))?></td><td><?=e(ucfirst($s['billing_period']))?> · <?=number_format((int)$s['duration_days'])?> days</td><td><?=e(date('j M Y',strtotime($s['starts_on'])))?> – <?=e(date('j M Y',strtotime($s['ends_on'])))?></td><td><?php if((int)$s['days_left']<=30):?><span class="count-pill"><?=$s['days_left']?> day<?=((int)$s['days_left']===1?'':'s')?></span><?php else:?><?=$s['days_left']?> days<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<div class="section-heading"><div><div class="eyebrow">AWAITING PAYMENT</div><h3>Pending subscription requests</h3></div><span class="count-pill"><?=count($pendingSubscriptions)?> pending</span></div><?php if(!$pendingSubscriptions):?><p class="muted">No pending requests for this year.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Plan</th><th>Pupils</th><th>Discount</th><th>Requested amount</th><th>Duration</th><th>Subscription dates</th><th>Action</th></tr></thead><tbody><?php foreach($pendingSubscriptions as $s):?><tr><td><?=e($s['school_name'])?></td><td><?=e($s['plan_name'])?></td><td><?=number_format((int)$s['pupil_count'])?></td><td><?=e(number_format((float)$s['discount_percent'],2))?>%</td><td><?=e($s['currency'])?> <?=e(number_format((float)$s['total_amount'],2))?></td><td><?=e(ucfirst($s['billing_period']))?> · <?=number_format((int)$s['duration_days'])?> days</td><td><?=e(date('j M Y',strtotime($s['starts_on'])))?> – <?=e(date('j M Y',strtotime($s['ends_on'])))?></td><td><form method="post" onsubmit="return confirm('Confirm the payment was received and activate this subscription?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="confirm_payment"><input type="hidden" name="subscription_id" value="<?=$s['id']?>"><input type="hidden" name="year" value="<?=$analysisYear?>"><button class="button primary" type="submit">Confirm payment</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
